      if(items.length>6){const more=node("details","terminal-history");more.append(node("summary","",String(items.length-6)+" additional evidence and recovery signals"));const list=node("div","terminal-history-list attention-list");for(const item of items.slice(6,20))list.append(cardFor(item));if(items.length>20)list.append(node("div","empty",String(items.length-20)+" more signals remain available in repository evidence."));more.append(list);target.append(more)}
